const ROOT = process.cwd(), P = (r) => path.join(ROOT, r);
const FILES = [{"path": "components/VideosView.tsx", "src": "\"use client\";\n\nimport { useEffect, useState } from \"react\";\nimport { Radio } from \"lucide-react\";\nimport { C } from \"@/lib/theme\";\nimport VideosGrid, { type Video } from \"@/components/VideosGrid\";\nimport { useLanguage } from \"@/lib/i18n/LanguageContext\";\n\nconst WRAP = \"mx-auto max-w-[1312px] px-6 md:px-16\";\n\nfunction CountUp({ value }: { value: number }) {\n  const [shown, setShown] = useState(value);\n  useEffect(() => {\n    if (window.matchMedia?.(\"(prefers-reduced-motion: reduce)\").matches) return setShown(value);\n    let raf = 0;\n    const start = performance.now();\n    setShown(0);\n    const tick = (now: number) => {\n      const p = Math.min(1, (now - start) / 900);\n      setShown(Math.round(value * (1 - Math.pow(1 - p, 3))));\n      if (p < 1) raf = requestAnimationFrame(tick);\n    };\n    raf = requestAnimationFrame(tick);\n    return () => cancelAnimationFrame(raf);\n  }, [value]);\n  return <>{String(shown).padStart(2, \"0\")}</>;\n}\n\nexport default function VideosView({ videos }: { videos: Video[] }) {\n  const { t, locale } = useLanguage();\n  const yt = videos.filter((v) => v.platform === \"YouTube\").length;\n  const tk = videos.filter((v) => v.platform === \"TikTok\").length;\n\n  return (\n    <main className=\"min-h-screen w-full cz-grid-bg pb-24\" style={{ color: C.paper }}>\n      <header className=\"border-b\" style={{ borderColor: C.line }}>\n        <div className={`${WRAP} pb-10 pt-14 md:pt-20`}>\n          <div className=\"flex items-center gap-2 text-[11px] uppercase tracking-[0.24em]\" style={{ color: C.radar }}>\n            <Radio size={14} className=\"cz-live\" aria-hidden=\"true\" />\n            <span>{t(\"common.fieldComms\")}</span>\n          </div>\n          <h1 className=\"cz-display mt-3 uppercase leading-[0.92]\" style={{ fontSize: \"clamp(2.8rem, 7vw, 5.5rem)\", fontWeight: 700, letterSpacing: \"0.01em\" }}>\n            {t(\"videos.titleLine1\")} <span style={{ color: C.amber }}>{t(\"videos.titleLine2\")}</span>\n          </h1>\n\n          <div className=\"mt-8 grid max-w-3xl grid-cols-2 gap-px border sm:grid-cols-4\" style={{ background: C.line, borderColor: C.line }}>\n            {[\n              { label: t(\"videos.logEntriesLabel\"), value: videos.length, color: C.amber },\n              { label: \"YouTube\", value: yt, color: C.paper },\n              { label: \"TikTok\", value: tk, color: C.paper },\n            ].map((s) => (\n              <div key={s.label} className=\"px-5 py-4\" style={{ background: C.panel }}>\n                <div className=\"text-[11px] uppercase tracking-[0.18em]\" style={{ color: C.muted }}>{s.label}</div>\n                <div className=\"cz-display mt-1 text-4xl leading-none tabular-nums\" style={{ color: s.color, fontWeight: 700 }}>\n                  <CountUp value={s.value} />\n                </div>\n              </div>\n            ))}\n            <div className=\"px-5 py-4\" style={{ background: C.panel }}>\n              <div className=\"text-[11px] uppercase tracking-[0.18em]\" style={{ color: C.muted }}>{t(\"videos.statusLabel\")}</div>\n              <div className=\"mt-2 flex items-center gap-2 text-sm uppercase tracking-widest\" style={{ color: C.radar, fontWeight: 700 }}>\n                <span className=\"relative inline-flex h-2 w-2\">\n                  <span className=\"cz-blink absolute inset-0 rounded-full\" style={{ background: C.radar }} />\n                  <span className=\"relative inline-block h-2 w-2 rounded-full\" style={{ background: C.radar }} />\n                </span>\n                {t(\"videos.statusValue\")}\n              </div>\n            </div>\n          </div>\n        </div>\n      </header>\n\n      <div className={WRAP} key={locale}>\n        <VideosGrid videos={videos} />\n      </div>\n    </main>\n  );\n}\n", "sig": "export default function VideosView", "drop": []}, {"path": "components/VideosGrid.tsx", "src": "\"use client\";\n\nimport { useEffect, useLayoutEffect, useMemo, useRef, useState, type JSX } from \"react\";\nimport { Play, ArrowUpRight, Crosshair, X, Search } from \"lucide-react\";\nimport { C } from \"@/lib/theme\";\nimport { useLanguage } from \"@/lib/i18n/LanguageContext\";\n\nexport type Platform = \"YouTube\" | \"TikTok\";\n\nexport interface Video {\n  title: string;\n  platform: Platform;\n  description: string;\n  category?: string;\n  thumbnail: string | null;\n  link: string;\n}\n\nconst PLATFORM_ICON: Record<Platform, JSX.Element> = {\n  YouTube: (\n    <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\">\n      <path d=\"M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.5 12 3.5 12 3.5s-7.5 0-9.4.6A3 3 0 0 0 .5 6.2 31 31 0 0 0 0 12a31 31 0 0 0 .5 5.8 3 3 0 0 0 2.1 2.1c1.9.6 9.4.6 9.4.6s7.5 0 9.4-.6a3 3 0 0 0 2.1-2.1A31 31 0 0 0 24 12a31 31 0 0 0-.5-5.8ZM9.6 15.5V8.5l6.3 3.5-6.3 3.5Z\" />\n    </svg>\n  ),\n  TikTok: (\n    <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\">\n      <path d=\"M16.6 2h-3.2v14.1a3.1 3.1 0 1 1-2.6-3.06V9.8a6.3 6.3 0 1 0 5.8 6.28V8.3a8.2 8.2 0 0 0 4.8 1.55V6.7a5 5 0 0 1-4.8-4.7Z\" />\n    </svg>\n  ),\n};\n\n// Arabic needs a native review.\nconst TEXT = {\n  en: {\n    search: \"Search videos\",\n    clear: \"Clear search\",\n    featured: \"Latest transmission\",\n    play: \"Play\",\n    watch: \"Watch transmission\",\n    openOn: (p: string) => `Open on ${p}`,\n    close: \"Close video\",\n    fieldClip: \"Field clip\",\n    noFeed: \"No feed capture\",\n  },\n  ar: {\n    search: \"ابحث عن فيديو\",\n    clear: \"مسح البحث\",\n    featured: \"أحدث بث\",\n    play: \"تشغيل\",\n    watch: \"شاهد البث\",\n    openOn: (p: string) => `افتح على ${p}`,\n    close: \"إغلاق الفيديو\",\n    fieldClip: \"مقطع ميداني\",\n    noFeed: \"لا توجد صورة\",\n  },\n};\n\nconst CSS = `\n@keyframes czv-in { from { opacity: 0; transform: translateY(18px) scale(0.98); } to { opacity: 1; transform: none; } }\n@keyframes czv-scan { from { transform: translateY(-100%); } to { transform: translateY(260%); } }\n@keyframes czv-pulse { 0% { box-shadow: 0 0 0 0 rgba(232,166,61,0.55); } 100% { box-shadow: 0 0 0 22px rgba(232,166,61,0); } }\n@keyframes czv-modal { from { opacity: 0; transform: scale(0.94) translateY(10px); } to { opacity: 1; transform: none; } }\n@keyframes czv-fade { from { opacity: 0; } to { opacity: 1; } }\n@keyframes czv-grad { 0% { background-position: 0% 50%; } 100% { background-position: 200% 50%; } }\n.czv-card { animation: czv-in 0.55s cubic-bezier(0.2, 0.7, 0.2, 1) both; transform: perspective(900px) rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg)); transition: transform 0.2s ease-out, border-color 0.3s ease; transform-style: preserve-3d; }\n.czv-card:hover { border-color: #8A6425 !important; }\n.czv-card::before { content: \"\"; position: absolute; inset: 0; z-index: 15; pointer-events: none; opacity: 0; transition: opacity 0.3s ease;\n  background: radial-gradient(280px circle at var(--mx, 50%) var(--my, 50%), rgba(232,166,61,0.14), transparent 70%); }\n.czv-card:hover::before { opacity: 1; }\n.czv-thumb { filter: grayscale(0.4) contrast(1.05); transition: transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1), filter 0.5s ease; }\n.czv-card:hover .czv-thumb, .czv-feature:hover .czv-thumb { filter: none; transform: scale(1.07); }\n.czv-scanline { position: absolute; left: 0; right: 0; top: 0; height: 40%; pointer-events: none; opacity: 0;\n  background: linear-gradient(180deg, transparent, rgba(232,166,61,0.18), transparent); }\n.czv-card:hover .czv-scanline { opacity: 1; animation: czv-scan 1.5s linear infinite; }\n.czv-playbtn { transition: transform 0.3s cubic-bezier(0.2, 0.7, 0.2, 1); }\n.czv-card:hover .czv-playbtn, .czv-feature:hover .czv-playbtn { transform: scale(1.12); }\n.czv-pulse { animation: czv-pulse 1.8s ease-out infinite; }\n.czv-modal { animation: czv-modal 0.3s cubic-bezier(0.2, 0.7, 0.2, 1) both; }\n.czv-backdrop { animation: czv-fade 0.25s ease both; }\n.czv-indicator { transition: left 0.35s cubic-bezier(0.2, 0.7, 0.2, 1), width 0.35s cubic-bezier(0.2, 0.7, 0.2, 1); }\n.czv-nofeed { background: linear-gradient(110deg, #0D100A, #1d2215, #0D100A, #1d2215); background-size: 200% 100%; animation: czv-grad 6s linear infinite; }\n@media (prefers-reduced-motion: reduce) {\n  .czv-card, .czv-pulse, .czv-modal, .czv-backdrop, .czv-nofeed, .czv-card:hover .czv-scanline { animation: none !important; }\n  .czv-card { transform: none !important; transition: none !important; }\n  .czv-thumb, .czv-playbtn, .czv-indicator { transition: none !important; }\n  .czv-card:hover .czv-thumb, .czv-feature:hover .czv-thumb, .czv-card:hover .czv-playbtn { transform: none !important; }\n}\n`;\n\nfunction youtubeId(link: string): string | null {\n  const m = link.match(/(?:v=|youtu\\.be\\/|shorts\\/|embed\\/|live\\/)([\\w-]{11})/);\n  return m ? m[1] : null;\n}\nconst embedUrl = (id: string) => `https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0&modestbranding=1`;\n\nfunction reducedMotion() {\n  return typeof window !== \"undefined\" && !!window.matchMedia?.(\"(prefers-reduced-motion: reduce)\").matches;\n}\n\n// 3D tilt + spotlight that follow the mouse\nfunction onTilt(e: React.MouseEvent<HTMLElement>) {\n  const el = e.currentTarget;\n  const r = el.getBoundingClientRect();\n  const px = (e.clientX - r.left) / r.width;\n  const py = (e.clientY - r.top) / r.height;\n  el.style.setProperty(\"--mx\", `${e.clientX - r.left}px`);\n  el.style.setProperty(\"--my\", `${e.clientY - r.top}px`);\n  if (reducedMotion()) return;\n  el.style.setProperty(\"--ry\", `${(px - 0.5) * 8}deg`);\n  el.style.setProperty(\"--rx\", `${(0.5 - py) * 6}deg`);\n}\nfunction offTilt(e: React.MouseEvent<HTMLElement>) {\n  e.currentTarget.style.setProperty(\"--rx\", \"0deg\");\n  e.currentTarget.style.setProperty(\"--ry\", \"0deg\");\n}\n\nconst BRACKETS = [\n  \"top-2 start-2 border-t border-s\",\n  \"top-2 end-2 border-t border-e\",\n  \"bottom-2 start-2 border-b border-s\",\n  \"bottom-2 end-2 border-b border-e\",\n];\n\nexport default function VideosGrid({ videos }: { videos: Video[] }) {\n  const { t, locale } = useLanguage();\n  const lang = locale === \"ar\" ? \"ar\" : \"en\";\n  const tx = TEXT[lang];\n\n  const platforms: Array<Platform | \"All\"> = [\"All\", ...Array.from(new Set(videos.map((v) => v.platform)))];\n  const [filter, setFilter] = useState<Platform | \"All\">(\"All\");\n  const [query, setQuery] = useState(\"\");\n  const [modal, setModal] = useState<Video | null>(null);\n  const [featurePlaying, setFeaturePlaying] = useState(false);\n\n  // sliding filter indicator\n  const btnRefs = useRef<Record<string, HTMLButtonElement | null>>({});\n  const [ind, setInd] = useState({ left: 0, width: 0 });\n  useLayoutEffect(() => {\n    const measure = () => {\n      const el = btnRefs.current[filter];\n      if (el) setInd({ left: el.offsetLeft, width: el.offsetWidth });\n    };\n    measure();\n    window.addEventListener(\"resize\", measure);\n    return () => window.removeEventListener(\"resize\", measure);\n  }, [filter, lang]);\n\n  // Esc closes the player\n  useEffect(() => {\n    if (!modal) return;\n    const onKey = (e: KeyboardEvent) => e.key === \"Escape\" && setModal(null);\n    document.addEventListener(\"keydown\", onKey);\n    const prev = document.body.style.overflow;\n    document.body.style.overflow = \"hidden\";\n    return () => {\n      document.removeEventListener(\"keydown\", onKey);\n      document.body.style.overflow = prev;\n    };\n  }, [modal]);\n\n  const counts = useMemo(() => {\n    const c: Record<string, number> = { All: videos.length };\n    for (const v of videos) c[v.platform] = (c[v.platform] ?? 0) + 1;\n    return c;\n  }, [videos]);\n\n  const q = query.trim().toLowerCase();\n  const shown = videos.filter(\n    (v) =>\n      (filter === \"All\" || v.platform === filter) &&\n      (!q || v.title.toLowerCase().includes(q) || v.description.toLowerCase().includes(q) || (v.category ?? \"\").toLowerCase().includes(q))\n  );\n\n  // Big featured player: newest YouTube video, only on the unfiltered view\n  const featured = !q && filter !== \"TikTok\" ? shown.find((v) => v.platform === \"YouTube\" && youtubeId(v.link)) ?? null : null;\n  const featuredId = featured ? youtubeId(featured.link) : null;\n  const rest = featured ? shown.filter((v) => v !== featured) : shown;\n\n  function openVideo(v: Video, e: React.MouseEvent) {\n    // YouTube plays in an on-page player; TikTok opens in a new tab\n    if (v.platform === \"YouTube\" && youtubeId(v.link) && !e.metaKey && !e.ctrlKey && !e.shiftKey) {\n      e.preventDefault();\n      setModal(v);\n    }\n  }\n\n  return (\n    <>\n      <style>{CSS}</style>\n\n      {/* Toolbar */}\n      <div className=\"sticky top-0 z-20 -mx-2 mt-8 flex flex-wrap items-center gap-4 px-2 py-3\" style={{ background: \"rgba(10,12,8,0.92)\", backdropFilter: \"blur(6px)\" }}>\n        <div className=\"relative flex border\" style={{ borderColor: C.amberDim }} role=\"group\">\n          <span aria-hidden=\"true\" className=\"czv-indicator absolute inset-y-0\" style={{ left: ind.left, width: ind.width, background: C.amber }} />\n          {platforms.map((p) => {\n            const active = filter === p;\n            return (\n              <button\n                key={p}\n                ref={(el) => {\n                  btnRefs.current[p] = el;\n                }}\n                aria-pressed={active}\n                onClick={() => {\n                  setFilter(p);\n                  setFeaturePlaying(false);\n                }}\n                className=\"relative z-10 inline-flex min-h-[44px] items-center gap-2 px-4 text-xs uppercase tracking-widest transition-colors duration-300\"\n                style={{ color: active ? C.void : C.paper, fontWeight: active ? 700 : 500 }}\n              >\n                {p !== \"All\" && PLATFORM_ICON[p]}\n                {p === \"All\" ? t(\"videos.all\") : p}\n                <span className=\"tabular-nums\" style={{ opacity: 0.65 }}>{counts[p] ?? 0}</span>\n              </button>\n            );\n          })}\n        </div>\n        <label className=\"relative flex-[1_1_220px]\">\n          <span className=\"sr-only\">{tx.search}</span>\n          <Search size={16} aria-hidden=\"true\" className=\"pointer-events-none absolute top-1/2 -translate-y-1/2\" style={{ insetInlineStart: 12, color: C.muted }} />\n          <input\n            type=\"search\"\n            value={query}\n            onChange={(e) => setQuery(e.target.value)}\n            placeholder={tx.search}\n            className=\"min-h-[44px] w-full border border-[#8A6425] bg-[#12150E] pe-10 ps-9 text-sm text-[#EDEAE0] transition-colors focus:border-[#E8A63D]\"\n          />\n          {query && (\n            <button onClick={() => setQuery(\"\")} aria-label={tx.clear} className=\"absolute top-1/2 inline-flex h-8 w-8 -translate-y-1/2 items-center justify-center\" style={{ insetInlineEnd: 6, color: C.muted }}>\n              <X size={15} aria-hidden=\"true\" />\n            </button>\n          )}\n        </label>\n      </div>\n\n      {/* Featured player */}\n      {featured && featuredId && (\n        <section className=\"czv-feature group mt-6 grid overflow-hidden border lg:grid-cols-[1.6fr_1fr]\" style={{ borderColor: C.amberDim, background: C.panel }}>\n          <div className=\"relative overflow-hidden\" style={{ aspectRatio: \"16 / 9\", background: \"#000\" }}>\n            {featurePlaying ? (\n              <iframe\n                src={embedUrl(featuredId)}\n                title={featured.title}\n                className=\"absolute inset-0 h-full w-full\"\n                allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\n                allowFullScreen\n              />\n            ) : (\n              <button onClick={() => setFeaturePlaying(true)} className=\"absolute inset-0 block h-full w-full\" aria-label={`${tx.play}: ${featured.title}`}>\n                {featured.thumbnail && (\n                  // eslint-disable-next-line @next/next/no-img-element\n                  <img src={featured.thumbnail} alt=\"\" className=\"czv-thumb h-full w-full object-cover\" />\n                )}\n                <span className=\"absolute inset-0\" style={{ background: \"linear-gradient(0deg, rgba(10,12,8,0.75), rgba(10,12,8,0.05) 60%)\" }} />\n                <span className=\"absolute inset-0 flex items-center justify-center\">\n                  <span className=\"czv-playbtn czv-pulse flex h-20 w-20 items-center justify-center rounded-full\" style={{ background: C.amber }}>\n                    <Play size={30} color={C.void} fill={C.void} aria-hidden=\"true\" />\n                  </span>\n                </span>\n              </button>\n            )}\n          </div>\n          <div className=\"flex flex-col justify-center gap-4 p-6 md:p-8\">\n            <div className=\"flex items-center gap-2 text-[11px] uppercase tracking-[0.24em]\" style={{ color: C.radar }}>\n              <span className=\"relative inline-flex h-2 w-2\">\n                <span className=\"cz-blink absolute inset-0 rounded-full\" style={{ background: C.radar }} />\n                <span className=\"relative inline-block h-2 w-2 rounded-full\" style={{ background: C.radar }} />\n              </span>\n              {tx.featured}\n            </div>\n            <h2 className=\"cz-display text-3xl uppercase leading-tight md:text-4xl\" style={{ fontWeight: 600 }} dir=\"auto\">\n              {featured.title}\n            </h2>\n            {featured.description && <p className=\"text-sm leading-relaxed\" style={{ color: C.muted }}>{featured.description}</p>}\n            <div className=\"flex flex-wrap gap-3\">\n              {!featurePlaying && (\n                <button\n                  onClick={() => setFeaturePlaying(true)}\n                  className=\"inline-flex min-h-[44px] items-center gap-2 px-5 text-xs uppercase tracking-widest\"\n                  style={{ background: C.amber, color: C.void, fontWeight: 700 }}\n                >\n                  <Play size={14} fill=\"currentColor\" aria-hidden=\"true\" />\n                  {tx.play}\n                </button>\n              )}\n              <a\n                href={featured.link}\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                className=\"inline-flex min-h-[44px] items-center gap-2 border px-5 text-xs uppercase tracking-widest transition-colors hover:bg-[#171B10]\"\n                style={{ borderColor: C.amberDim, color: C.paper }}\n              >\n                {PLATFORM_ICON.YouTube}\n                {tx.openOn(\"YouTube\")}\n                <ArrowUpRight size={14} className=\"rtl:-scale-x-100\" aria-hidden=\"true\" />\n              </a>\n            </div>\n          </div>\n        </section>\n      )}\n\n      {shown.length === 0 ? (\n        <p className=\"mt-8 border px-4 py-12 text-center text-sm\" style={{ borderColor: C.line, background: C.panel, color: C.muted }}>\n          {t(\"videos.noVideos\")}\n        </p>\n      ) : (\n        <section key={`${filter}-${q}`} className=\"mt-6 grid gap-5 md:grid-cols-2 lg:grid-cols-3\" style={{ perspective: \"1200px\" }}>\n          {rest.map((video, i) => (\n            <a\n              key={video.link}\n              href={video.link}\n              target=\"_blank\"\n              rel=\"noopener noreferrer\"\n              onClick={(e) => openVideo(video, e)}\n              onMouseMove={onTilt}\n              onMouseLeave={offTilt}\n              className=\"czv-card group relative block border\"\n              style={{ background: C.panel, borderColor: C.line, animationDelay: `${Math.min(i, 12) * 0.05}s` }}\n            >\n              {BRACKETS.map((pos) => (\n                <span key={pos} aria-hidden=\"true\" className={`pointer-events-none absolute z-20 h-3 w-3 opacity-0 transition-opacity duration-300 group-hover:opacity-100 ${pos}`} style={{ borderColor: C.amber }} />\n              ))}\n\n              <div className=\"flex items-center justify-between border-b px-4 py-2.5 text-[11px] uppercase tracking-widest\" style={{ borderColor: C.line, color: C.muted }}>\n                <span className=\"flex items-center gap-1.5\" style={{ color: video.platform === \"YouTube\" ? C.paper : C.radar }}>\n                  {PLATFORM_ICON[video.platform]}\n                  {video.platform}\n                </span>\n                <span className=\"tabular-nums\">Log {String(i + (featured ? 2 : 1)).padStart(2, \"0\")}</span>\n              </div>\n\n              <div className=\"relative overflow-hidden\" style={{ aspectRatio: \"16 / 9\", background: \"#000\" }}>\n                {video.thumbnail ? (\n                  // eslint-disable-next-line @next/next/no-img-element\n                  <img src={video.thumbnail} alt=\"\" loading=\"lazy\" className=\"czv-thumb h-full w-full object-cover\" />\n                ) : (\n                  <div className=\"czv-nofeed flex h-full w-full flex-col items-center justify-center gap-2\" style={{ color: C.lineStrong }}>\n                    <Crosshair size={28} aria-hidden=\"true\" />\n                    <span className=\"text-[11px] uppercase tracking-widest\">{tx.noFeed}</span>\n                  </div>\n                )}\n                <span className=\"czv-scanline\" aria-hidden=\"true\" />\n                <span className=\"absolute inset-0 flex items-center justify-center\" style={{ background: \"linear-gradient(0deg, rgba(10,12,8,0.55), rgba(10,12,8,0) 55%)\" }}>\n                  <span className=\"czv-playbtn flex h-12 w-12 items-center justify-center rounded-full opacity-90 group-hover:opacity-100\" style={{ background: C.amber, boxShadow: \"0 0 24px rgba(232,166,61,0.45)\" }}>\n                    <Play size={18} color={C.void} fill={C.void} aria-hidden=\"true\" />\n                  </span>\n                </span>\n              </div>\n\n              <div className=\"p-4\">\n                <span className=\"mb-3 inline-block border px-2 py-1 text-[10px] uppercase tracking-widest\" style={{ borderColor: C.lineStrong, color: C.radar }}>\n                  {video.category ?? tx.fieldClip}\n                </span>\n                <h3 className=\"text-base leading-snug\" style={{ color: C.paper, fontWeight: 600, minHeight: \"2.8em\" }} dir=\"auto\">\n                  {video.title}\n                </h3>\n                {video.description && (\n                  <p className=\"mt-2 text-sm\" style={{ color: C.muted, display: \"-webkit-box\", WebkitLineClamp: 2, WebkitBoxOrient: \"vertical\", overflow: \"hidden\" }}>\n                    {video.description}\n                  </p>\n                )}\n                <div className=\"mt-4 flex items-center justify-between border-t pt-3 text-xs uppercase tracking-widest\" style={{ borderColor: C.line, color: C.amber, fontWeight: 600 }}>\n                  <span>{tx.watch}</span>\n                  <ArrowUpRight size={15} className=\"rtl:-scale-x-100 transition-transform group-hover:-translate-y-0.5\" aria-hidden=\"true\" />\n                </div>\n              </div>\n            </a>\n          ))}\n        </section>\n      )}\n\n      {/* On-page player */}\n      {modal && youtubeId(modal.link) && (\n        <div className=\"fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-10\" role=\"dialog\" aria-modal=\"true\" aria-label={modal.title}>\n          <button className=\"czv-backdrop absolute inset-0\" style={{ background: \"rgba(5,6,4,0.88)\", backdropFilter: \"blur(6px)\" }} onClick={() => setModal(null)} aria-label={tx.close} />\n          <div className=\"czv-modal relative w-full max-w-5xl border\" style={{ borderColor: C.amberDim, background: C.void, boxShadow: \"0 30px 80px rgba(0,0,0,0.6)\" }}>\n            <div className=\"flex items-center gap-3 border-b px-4 py-2.5\" style={{ borderColor: C.line }}>\n              <span style={{ color: C.paper }}>{PLATFORM_ICON.YouTube}</span>\n              <span className=\"min-w-0 flex-1 truncate text-sm\" style={{ color: C.paper, fontWeight: 600 }} dir=\"auto\">{modal.title}</span>\n              <a href={modal.link} target=\"_blank\" rel=\"noopener noreferrer\" className=\"hidden items-center gap-1 text-xs uppercase tracking-widest sm:inline-flex\" style={{ color: C.amber }}>\n                {tx.openOn(\"YouTube\")}\n                <ArrowUpRight size={13} className=\"rtl:-scale-x-100\" aria-hidden=\"true\" />\n              </a>\n              <button onClick={() => setModal(null)} autoFocus aria-label={tx.close} className=\"inline-flex h-9 w-9 items-center justify-center transition-colors hover:bg-[#171B10]\" style={{ color: C.paper }}>\n                <X size={18} aria-hidden=\"true\" />\n              </button>\n            </div>\n            <div className=\"relative\" style={{ aspectRatio: \"16 / 9\" }}>\n              <iframe\n                src={embedUrl(youtubeId(modal.link)!)}\n                title={modal.title}\n                className=\"absolute inset-0 h-full w-full\"\n                allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\n                allowFullScreen\n              />\n            </div>\n          </div>\n        </div>\n      )}\n    </>\n  );\n}\n", "sig": "export default function VideosGrid", "drop": []}, {"path": "components/TournamentsView.tsx", "src": "\"use client\";\n\nimport { useEffect, useMemo, useState } from \"react\";\nimport Link from \"next/link\";\nimport { Radio, Trophy, ArrowUpRight, Crown, Swords, Users, CalendarDays, Sparkles, Medal, Timer } from \"lucide-react\";\nimport { C, DISCORD_URL } from \"@/lib/theme\";\nimport { useLanguage } from \"@/lib/i18n/LanguageContext\";\nimport { createClient } from \"@/lib/supabase/client\";\n\n// ---------------------------------------------------------------------------\n// UPCOMING EVENTS (optional)\n// These are the placeholder events from before. They stay hidden until you set\n// SHOW_EVENTS to true. Add a `date` (e.g. \"2026-11-20T18:00:00Z\") to show a live countdown.\n// Past tournaments and their champions appear automatically from logged matches.\n// ---------------------------------------------------------------------------\nconst SHOW_EVENTS = false;\n\ntype Status = \"Registration Open\" | \"Coming Soon\" | \"Active\";\n\ninterface Event {\n  name: string;\n  status: Status;\n  info: string;\n  date?: string;\n}\n\nconst events: Event[] = [\n  { name: \"Commander Tournament 2026\", status: \"Registration Open\", info: \"1v1 and team battles.\" },\n  { name: \"Clan Championship\", status: \"Coming Soon\", info: \"International Generals Zero Hour event.\" },\n  { name: \"Weekly Community War\", status: \"Active\", info: \"Play with the best players.\" },\n];\n\ntype TMatch = { id: string; participants: string[] | null; winners: string[] | null; tournament_name: string | null; round: string | null; created_at: string };\n\nconst WRAP = \"mx-auto max-w-[1312px] px-6 md:px-16\";\nconst PAGE = 1000;\n\n// Arabic needs a native review.\nconst TEXT = {\n  en: {\n    held: \"Tournaments held\",\n    matches: \"Tournament matches\",\n    players: \"Competitors\",\n    crowned: \"Champions crowned\",\n    standings: \"View standings\",\n    upcoming: \"Upcoming events\",\n    hall: \"Hall of champions\",\n    hallSub: \"Every tournament logged on Commander and who took the crown.\",\n    champion: \"Champion\",\n    leader: \"Leader\",\n    open: \"Open standings\",\n    days: \"d\",\n    hours: \"h\",\n    mins: \"m\",\n    secs: \"s\",\n    liveNow: \"Live now\",\n    startsIn: \"Starts in\",\n    nextEvent: \"Next event\",\n    nextEventDesc: \"The next tournament will be announced on Discord. Join so you don't miss registration.\",\n  },\n  ar: {\n    held: \"البطولات المُقامة\",\n    matches: \"مباريات البطولات\",\n    players: \"المتنافسون\",\n    crowned: \"الأبطال المتوَّجون\",\n    standings: \"عرض الترتيب\",\n    upcoming: \"البطولات القادمة\",\n    hall: \"قاعة الأبطال\",\n    hallSub: \"كل بطولة سُجّلت في كوماندر ومن نال لقبها.\",\n    champion: \"البطل\",\n    leader: \"المتصدّر\",\n    open: \"افتح الترتيب\",\n    days: \"ي\",\n    hours: \"س\",\n    mins: \"د\",\n    secs: \"ث\",\n    liveNow: \"مباشر الآن\",\n    startsIn: \"تبدأ خلال\",\n    nextEvent: \"البطولة القادمة\",\n    nextEventDesc: \"سيتم الإعلان عن البطولة القادمة على ديسكورد. انضم حتى لا يفوتك التسجيل.\",\n  },\n};\n\nconst CSS = `\n@keyframes czh-in { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: none; } }\n@keyframes czh-rays { to { transform: rotate(360deg); } }\n@keyframes czh-float { 0%, 100% { transform: translateY(0) rotate(-2deg); } 50% { transform: translateY(-10px) rotate(2deg); } }\n@keyframes czh-twinkle { 0%, 100% { opacity: 0; transform: scale(0.3) rotate(0deg); } 50% { opacity: 1; transform: scale(1) rotate(45deg); } }\n@keyframes czh-shine { 0% { transform: translateX(-130%) skewX(-20deg); } 55%, 100% { transform: translateX(240%) skewX(-20deg); } }\n@keyframes czh-tick { from { transform: translateY(-40%); opacity: 0; } to { transform: none; opacity: 1; } }\n@keyframes czh-orbit { to { transform: rotate(360deg); } }\n.czh-in { animation: czh-in 0.6s cubic-bezier(0.2, 0.7, 0.2, 1) both; }\n.czh-rays { animation: czh-rays 22s linear infinite; }\n.czh-float { animation: czh-float 4s ease-in-out infinite; }\n.czh-spark { position: absolute; width: 8px; height: 8px; background: #E8A63D; clip-path: polygon(50% 0, 62% 38%, 100% 50%, 62% 62%, 50% 100%, 38% 62%, 0 50%, 38% 38%); animation: czh-twinkle 2.6s ease-in-out infinite; }\n.czh-card { position: relative; overflow: hidden; transition: transform 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease; }\n.czh-card:hover { transform: translateY(-5px); border-color: #8A6425 !important; box-shadow: 0 18px 40px rgba(0,0,0,0.35), 0 0 30px rgba(232,166,61,0.12); }\n.czh-card::after { content: \"\"; position: absolute; top: 0; bottom: 0; width: 35%; pointer-events: none; transform: translateX(-130%) skewX(-20deg);\n  background: linear-gradient(90deg, transparent, rgba(232,166,61,0.16), transparent); }\n.czh-card:hover::after { animation: czh-shine 1s ease; }\n.czh-tick { display: inline-block; animation: czh-tick 0.35s ease-out both; }\n.czh-orbit { animation: czh-orbit 9s linear infinite; }\n@media (prefers-reduced-motion: reduce) {\n  .czh-in, .czh-rays, .czh-float, .czh-spark, .czh-tick, .czh-orbit, .czh-card:hover::after { animation: none !important; }\n  .czh-card { transition: none !important; }\n  .czh-card:hover { transform: none !important; }\n}\n`;\n\nfunction CountUp({ value }: { value: number }) {\n  const [shown, setShown] = useState(value);\n  useEffect(() => {\n    if (window.matchMedia?.(\"(prefers-reduced-motion: reduce)\").matches) return setShown(value);\n    let raf = 0;\n    const start = performance.now();\n    setShown(0);\n    const tick = (now: number) => {\n      const p = Math.min(1, (now - start) / 1000);\n      setShown(Math.round(value * (1 - Math.pow(1 - p, 3))));\n      if (p < 1) raf = requestAnimationFrame(tick);\n    };\n    raf = requestAnimationFrame(tick);\n    return () => cancelAnimationFrame(raf);\n  }, [value]);\n  return <>{shown}</>;\n}\n\nfunction Countdown({ date, tx }: { date: string; tx: (typeof TEXT)[\"en\"] }) {\n  const target = new Date(date).getTime();\n  const [now, setNow] = useState<number | null>(null);\n  useEffect(() => {\n    setNow(Date.now());\n    const id = setInterval(() => setNow(Date.now()), 1000);\n    return () => clearInterval(id);\n  }, []);\n  if (now === null || !Number.isFinite(target)) return null;\n  const diff = Math.max(0, target - now);\n  if (diff === 0) {\n    return (\n      <span className=\"inline-flex items-center gap-2 text-sm uppercase tracking-widest\" style={{ color: C.radar, fontWeight: 700 }}>\n        <span className=\"cz-blink inline-block h-2 w-2 rounded-full\" style={{ background: C.radar }} />\n        {tx.liveNow}\n      </span>\n    );\n  }\n  const parts = [\n    [Math.floor(diff / 86400000), tx.days],\n    [Math.floor(diff / 3600000) % 24, tx.hours],\n    [Math.floor(diff / 60000) % 60, tx.mins],\n    [Math.floor(diff / 1000) % 60, tx.secs],\n  ] as const;\n  return (\n    <div className=\"flex gap-2\" dir=\"ltr\" aria-label={tx.startsIn}>\n      {parts.map(([v, u], i) => (\n        <div key={i} className=\"min-w-[52px] border px-2 py-1.5 text-center\" style={{ borderColor: C.amberDim, background: C.void }}>\n          <span key={v} className=\"czh-tick cz-display text-2xl leading-none tabular-nums\" style={{ color: C.amber, fontWeight: 700 }}>\n            {String(v).padStart(2, \"0\")}\n          </span>\n          <span className=\"ms-0.5 text-[10px] uppercase\" style={{ color: C.muted }}>{u}</span>\n        </div>\n      ))}\n    </div>\n  );\n}\n\nconst STATUS_STYLE: Record<Status, { color: string; live: boolean }> = {\n  \"Registration Open\": { color: C.radar, live: true },\n  Active: { color: C.radar, live: true },\n  \"Coming Soon\": { color: C.muted, live: false },\n};\n\nexport default function TournamentsView() {\n  const { t, locale } = useLanguage();\n  const lang = locale === \"ar\" ? \"ar\" : \"en\";\n  const tx = TEXT[lang];\n\n  const STATUS_LABEL: Record<Status, string> = {\n    \"Registration Open\": t(\"tournaments.statusRegistrationOpen\"),\n    Active: t(\"tournaments.statusActive\"),\n    \"Coming Soon\": t(\"tournaments.statusComingSoon\"),\n  };\n\n  const [matches, setMatches] = useState<TMatch[]>([]);\n  const [avatars, setAvatars] = useState<Record<string, string | null>>({});\n  const [loaded, setLoaded] = useState(false);\n\n  useEffect(() => {\n    const supabase = createClient();\n    let cancelled = false;\n    (async () => {\n      const all: TMatch[] = [];\n      for (let from = 0; from < 50_000; from += PAGE) {\n        const { data, error } = await supabase\n          .from(\"matches\")\n          .select(\"id, participants, winners, tournament_name, round, created_at\")\n          .not(\"tournament_name\", \"is\", null)\n          .order(\"created_at\", { ascending: false })\n          .range(from, from + PAGE - 1);\n        if (error) {\n          console.warn(\"[tournaments] could not read matches:\", error.message);\n          break;\n        }\n        const rows = (data ?? []) as TMatch[];\n        all.push(...rows);\n        if (rows.length < PAGE) break;\n      }\n      if (cancelled) return;\n      setMatches(all);\n      setLoaded(true);\n      const names = Array.from(new Set(all.flatMap((m) => m.winners ?? [])));\n      if (names.length) {\n        const { data } = await supabase.from(\"profiles\").select(\"username, avatar_url\").in(\"username\", names.slice(0, 500));\n        const map: Record<string, string | null> = {};\n        for (const p of (data ?? []) as { username: string; avatar_url: string | null }[]) map[p.username] = p.avatar_url;\n        if (!cancelled) setAvatars(map);\n      }\n    })();\n    return () => {\n      cancelled = true;\n    };\n  }, []);\n\n  // Each tournament with its champion (winners of the latest \"Final\"), or its leader\n  const hall = useMemo(() => {\n    const by = new Map<string, TMatch[]>();\n    for (const m of matches) {\n      if (!m.tournament_name) continue;\n      const list = by.get(m.tournament_name) ?? [];\n      list.push(m);\n      by.set(m.tournament_name, list);\n    }\n    const isFinal = (r: string) => /final|نهائي/i.test(r) && !/semi|quarter|نصف|ربع|1\\/2|1\\/4/i.test(r);\n    return Array.from(by.entries())\n      .map(([name, list]) => {\n        const times = list.map((m) => new Date(m.created_at).getTime());\n        const finals = list.filter((m) => m.round && isFinal(m.round)).sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());\n        let champs: string[] = [];\n        let decided = false;\n        if (finals[0]) {\n          champs = finals[0].winners ?? [];\n          decided = true;\n        } else {\n          const wins = new Map<string, number>();\n          for (const m of list) for (const w of m.winners ?? []) wins.set(w, (wins.get(w) ?? 0) + 1);\n          const top = Array.from(wins.entries()).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0];\n          champs = top ? [top[0]] : [];\n        }\n        return {\n          name,\n          matches: list.length,\n          players: new Set(list.flatMap((m) => m.participants ?? [])).size,\n          first: Math.min(...times),\n          last: Math.max(...times),\n          champs,\n          decided,\n        };\n      })\n      .sort((a, b) => b.last - a.last);\n  }, [matches]);\n\n  const totals = useMemo(\n    () => ({\n      held: hall.length,\n      matches: matches.length,\n      players: new Set(matches.flatMap((m) => m.participants ?? [])).size,\n      crowned: new Set(hall.filter((h) => h.decided).flatMap((h) => h.champs)).size,\n    }),\n    [hall, matches]\n  );\n\n  const shownEvents = SHOW_EVENTS ? events : [];\n  const activeCount = shownEvents.filter((e) => e.status !== \"Coming Soon\").length;\n  const fmt = (ms: number) => new Date(ms).toLocaleDateString(lang === \"ar\" ? \"ar-EG\" : \"en-US\", { month: \"short\", day: \"numeric\", year: \"numeric\" });\n  const nothingYet = loaded && hall.length === 0 && shownEvents.length === 0;\n\n  return (\n    <main className=\"min-h-screen w-full cz-grid-bg pb-24\" style={{ color: C.paper }}>\n      <style>{CSS}</style>\n\n      {/* ================= HERO ================= */}\n      <section className=\"relative overflow-hidden border-b\" style={{ borderColor: C.line }}>\n        <div aria-hidden=\"true\" className=\"pointer-events-none absolute end-[-10%] top-1/2 h-[720px] w-[720px] -translate-y-1/2 opacity-70\">\n          <div className=\"czh-rays absolute inset-0 rounded-full\" style={{ background: \"repeating-conic-gradient(from 0deg, rgba(232,166,61,0.09) 0deg 5deg, transparent 5deg 15deg)\", maskImage: \"radial-gradient(circle, black 20%, transparent 68%)\", WebkitMaskImage: \"radial-gradient(circle, black 20%, transparent 68%)\" }} />\n        </div>\n        {[[\"8%\", \"22%\", \"0s\"], [\"46%\", \"12%\", \"1.1s\"], [\"70%\", \"30%\", \"0.5s\"], [\"86%\", \"70%\", \"1.7s\"], [\"58%\", \"78%\", \"2.2s\"], [\"30%\", \"82%\", \"0.9s\"]].map(([l, tp, d], i) => (\n          <span key={i} aria-hidden=\"true\" className=\"czh-spark\" style={{ left: l, top: tp, animationDelay: d }} />\n        ))}\n\n        <div className={`${WRAP} relative grid gap-10 pb-14 pt-14 md:pt-20 lg:grid-cols-[1fr_auto] lg:items-center`}>\n          <div className=\"czh-in\">\n            <div className=\"flex items-center gap-2 text-[11px] uppercase tracking-[0.24em]\" style={{ color: C.radar }}>\n              <Radio size={14} className=\"cz-live\" aria-hidden=\"true\" />\n              <span>{t(\"common.fieldComms\")}</span>\n            </div>\n            <h1 className=\"cz-display mt-3 uppercase leading-[0.9]\" style={{ fontSize: \"clamp(3rem, 8vw, 6.5rem)\", fontWeight: 700 }}>\n              <span style={{ color: C.amber }}>{t(\"tournaments.title\")}</span>\n            </h1>\n            <p className=\"mt-4 text-sm uppercase tracking-widest\" style={{ color: C.muted }}>\n              {t(\"tournaments.tags\")}\n            </p>\n            <div className=\"mt-8 flex flex-wrap gap-3\">\n              <Link\n                href=\"/tournaments/standings\"\n                className=\"inline-flex min-h-[52px] items-center gap-2 px-7 text-sm uppercase tracking-[0.12em]\"\n                style={{ background: C.amber, color: C.void, fontWeight: 700, boxShadow: \"0 0 34px rgba(232,166,61,0.3)\" }}\n              >\n                <Medal size={16} aria-hidden=\"true\" />\n                {tx.standings}\n              </Link>\n              <a\n                href={DISCORD_URL}\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n                className=\"inline-flex min-h-[52px] items-center gap-2 border px-6 text-sm uppercase tracking-[0.12em] transition-colors hover:bg-[#171B10]\"\n                style={{ borderColor: C.amberDim, color: C.paper, fontWeight: 600 }}\n              >\n                {t(\"tournaments.getNotified\")}\n                <ArrowUpRight size={15} className=\"rtl:-scale-x-100\" aria-hidden=\"true\" />\n              </a>\n            </div>\n          </div>\n\n          {/* floating trophy with orbiting ring */}\n          <div className=\"relative mx-auto hidden h-64 w-64 items-center justify-center lg:flex\" aria-hidden=\"true\">\n            <div className=\"czh-orbit absolute inset-0 rounded-full\" style={{ border: `1px dashed ${C.amberDim}` }}>\n              <span className=\"absolute -top-1.5 start-1/2 h-3 w-3 -translate-x-1/2 rounded-full\" style={{ background: C.amber, boxShadow: \"0 0 14px #E8A63D\" }} />\n            </div>\n            <div className=\"absolute inset-8 rounded-full\" style={{ border: `1px solid ${C.line}`, background: \"radial-gradient(circle, rgba(232,166,61,0.18), transparent 70%)\" }} />\n            <Trophy size={110} className=\"czh-float\" style={{ color: C.amber, filter: \"drop-shadow(0 0 24px rgba(232,166,61,0.45))\" }} />\n          </div>\n        </div>\n\n        {/* stats */}\n        <div className={`${WRAP} relative pb-10`}>\n          <div className=\"czh-in grid grid-cols-2 gap-px border sm:grid-cols-4\" style={{ background: C.line, borderColor: C.line, animationDelay: \"0.15s\" }}>\n            {[\n              { icon: Trophy, label: tx.held, value: totals.held },\n              { icon: Swords, label: tx.matches, value: totals.matches },\n              { icon: Users, label: tx.players, value: totals.players },\n              { icon: Crown, label: tx.crowned, value: totals.crowned },\n            ].map((s) => (\n              <div key={s.label} className=\"px-5 py-4\" style={{ background: C.panel }}>\n                <div className=\"flex items-center gap-1.5 text-[11px] uppercase tracking-[0.18em]\" style={{ color: C.muted }}>\n                  <s.icon size={12} aria-hidden=\"true\" />\n                  {s.label}\n                </div>\n                <div className=\"cz-display mt-1 text-4xl leading-none tabular-nums\" style={{ color: C.amber, fontWeight: 700 }}>\n                  {loaded ? <CountUp value={s.value} /> : \"—\"}\n                </div>\n              </div>\n            ))}\n          </div>\n        </div>\n      </section>\n\n      <div className={WRAP}>\n        {/* ================= UPCOMING ================= */}\n        <section className=\"mt-14\">\n          <div className=\"mb-5 flex flex-wrap items-end justify-between gap-3\">\n            <h2 className=\"cz-display flex items-center gap-2.5 text-3xl uppercase md:text-4xl\" style={{ fontWeight: 600 }}>\n              <CalendarDays size={22} style={{ color: C.amber }} aria-hidden=\"true\" />\n              {tx.upcoming}\n            </h2>\n            {shownEvents.length > 0 && (\n              <span className=\"text-xs uppercase tracking-widest\" style={{ color: C.muted }}>\n                {t(\"tournaments.eventsLabel\")} <b style={{ color: C.paper }}>{String(shownEvents.length).padStart(2, \"0\")}</b>\n                <span className=\"mx-3\">·</span>\n                {t(\"tournaments.openNowLabel\")} <b style={{ color: C.radar }}>{String(activeCount).padStart(2, \"0\")}</b>\n              </span>\n            )}\n          </div>\n\n          {shownEvents.length > 0 ? (\n            <div className=\"grid gap-5 md:grid-cols-2 lg:grid-cols-3\">\n              {shownEvents.map((event, i) => {\n                const st = STATUS_STYLE[event.status];\n                return (\n                  <div key={event.name} className=\"czh-card czh-in border p-6\" style={{ background: C.panel, borderColor: C.line, animationDelay: `${i * 0.08}s` }}>\n                    <div className=\"flex items-center justify-between\">\n                      <Trophy size={24} style={{ color: C.amber }} aria-hidden=\"true\" />\n                      <span className=\"flex items-center gap-1.5 border px-2 py-1 text-[10px] uppercase tracking-widest\" style={{ borderColor: C.lineStrong, color: st.color }}>\n                        <span className={st.live ? \"cz-live\" : \"\"} style={{ width: 6, height: 6, borderRadius: \"50%\", background: st.color, display: \"inline-block\" }} />\n                        {STATUS_LABEL[event.status]}\n                      </span>\n                    </div>\n                    <h3 className=\"cz-display mt-5 text-2xl uppercase\" style={{ fontWeight: 600 }}>{event.name}</h3>\n                    <p className=\"mt-2 text-sm\" style={{ color: C.muted }}>{event.info}</p>\n                    {event.date && (\n                      <div className=\"mt-5\">\n                        <div className=\"mb-2 flex items-center gap-1.5 text-[11px] uppercase tracking-[0.18em]\" style={{ color: C.muted }}>\n                          <Timer size={12} aria-hidden=\"true\" />\n                          {tx.startsIn}\n                        </div>\n                        <Countdown date={event.date} tx={tx} />\n                      </div>\n                    )}\n                  </div>\n                );\n              })}\n            </div>\n          ) : (\n            <a\n              href={DISCORD_URL}\n              target=\"_blank\"\n              rel=\"noopener noreferrer\"\n              className=\"czh-card czh-in group flex flex-col gap-5 border p-6 md:flex-row md:items-center md:p-8\"\n              style={{ background: \"linear-gradient(120deg, rgba(143,191,79,0.08), #12150E 50%)\", borderColor: C.line }}\n            >\n              <span className=\"relative flex h-16 w-16 shrink-0 items-center justify-center rounded-full\" style={{ border: `1px solid rgba(143,191,79,0.5)` }} aria-hidden=\"true\">\n                <span className=\"czh-orbit absolute inset-0 rounded-full\" style={{ background: \"conic-gradient(from 0deg, rgba(143,191,79,0) 0deg, rgba(143,191,79,0) 280deg, rgba(143,191,79,0.55) 360deg)\" }} />\n                <Radio size={24} style={{ color: C.radar }} />\n              </span>\n              <div className=\"min-w-0 flex-1\">\n                <div className=\"text-[11px] uppercase tracking-[0.24em]\" style={{ color: C.radar }}>{tx.nextEvent}</div>\n                <div className=\"cz-display mt-1 text-2xl uppercase md:text-3xl\" style={{ fontWeight: 600 }}>{t(\"tournaments.comingSoon\")}</div>\n                <p className=\"mt-2 max-w-xl text-sm\" style={{ color: C.muted }}>{tx.nextEventDesc}</p>\n              </div>\n              <span className=\"inline-flex min-h-[44px] shrink-0 items-center gap-2 px-5 text-xs uppercase tracking-widest\" style={{ background: C.amber, color: C.void, fontWeight: 700 }}>\n                {t(\"tournaments.getNotified\")}\n                <ArrowUpRight size={14} className=\"rtl:-scale-x-100\" aria-hidden=\"true\" />\n              </span>\n            </a>\n          )}\n        </section>\n\n        {/* ================= HALL OF CHAMPIONS ================= */}\n        <section className=\"mt-16\">\n          <h2 className=\"cz-display flex items-center gap-2.5 text-3xl uppercase md:text-4xl\" style={{ fontWeight: 600 }}>\n            <Crown size={22} style={{ color: C.amber }} aria-hidden=\"true\" />\n            {tx.hall}\n          </h2>\n          <p className=\"mt-2 text-sm\" style={{ color: C.muted }}>{tx.hallSub}</p>\n\n          {!loaded ? (\n            <div className=\"mt-6 grid gap-5 md:grid-cols-2 lg:grid-cols-3\" aria-hidden=\"true\">\n              {[0, 1, 2].map((i) => <div key={i} className=\"h-56 border\" style={{ background: C.panel, borderColor: C.line, opacity: 0.6 }} />)}\n            </div>\n          ) : nothingYet ? (\n            <div className=\"mt-6 border px-6 py-14 text-center\" style={{ background: C.panel, borderColor: C.line }}>\n              <Trophy size={36} className=\"mx-auto\" style={{ color: C.lineStrong }} aria-hidden=\"true\" />\n              <p className=\"mx-auto mt-4 max-w-md text-sm\" style={{ color: C.muted }}>{t(\"tournaments.comingSoonDesc\")}</p>\n            </div>\n          ) : (\n            <div className=\"mt-6 grid gap-5 md:grid-cols-2 lg:grid-cols-3\">\n              {hall.map((h, i) => (\n                <Link\n                  key={h.name}\n                  href={`/tournaments/standings?t=${encodeURIComponent(h.name)}`}\n                  className=\"czh-card czh-in group flex flex-col border\"\n                  style={{ background: i === 0 ? \"linear-gradient(160deg, rgba(232,166,61,0.12), #12150E 55%)\" : C.panel, borderColor: i === 0 ? C.amberDim : C.line, animationDelay: `${Math.min(i, 9) * 0.07}s` }}\n                >\n                  <div className=\"flex items-center justify-between border-b px-5 py-3 text-[11px] uppercase tracking-widest\" style={{ borderColor: C.line, color: C.muted }}>\n                    <span className=\"inline-flex items-center gap-1.5\"><CalendarDays size={12} aria-hidden=\"true\" />{fmt(h.last)}</span>\n                    <span className=\"inline-flex items-center gap-3\">\n                      <span className=\"inline-flex items-center gap-1\"><Swords size={12} aria-hidden=\"true\" />{h.matches}</span>\n                      <span className=\"inline-flex items-center gap-1\"><Users size={12} aria-hidden=\"true\" />{h.players}</span>\n                    </span>\n                  </div>\n                  <div className=\"flex flex-1 flex-col p-5\">\n                    <h3 className=\"cz-display text-2xl uppercase leading-tight\" style={{ fontWeight: 600 }} dir=\"auto\">{h.name}</h3>\n                    <div className=\"mt-5 flex items-center gap-1.5 text-[11px] uppercase tracking-[0.2em]\" style={{ color: C.amber }}>\n                      {h.decided ? <Trophy size={13} aria-hidden=\"true\" /> : <Sparkles size={13} aria-hidden=\"true\" />}\n                      {h.decided ? tx.champion : tx.leader}\n                    </div>\n                    <div className=\"mt-3 flex items-center gap-3\">\n                      <div className=\"flex -space-x-3 rtl:space-x-reverse\">\n                        {h.champs.slice(0, 4).map((p) => (\n                          // eslint-disable-next-line @next/next/no-img-element\n                          <img key={p} src={avatars[p] || \"/default-avatar.svg\"} alt=\"\" className=\"h-11 w-11 rounded-full object-cover\" style={{ border: `2px solid ${C.amber}`, background: C.void }} />\n                        ))}\n                      </div>\n                      <div className=\"min-w-0 truncate text-base\" style={{ color: C.paper, fontWeight: 600 }}>\n                        {h.champs.join(\", \") || \"—\"}\n                      </div>\n                    </div>\n                    <div className=\"mt-auto flex items-center justify-between border-t pt-3 text-xs uppercase tracking-widest\" style={{ borderColor: C.line, color: C.amber, fontWeight: 600, marginTop: \"1.25rem\" }}>\n                      <span>{tx.open}</span>\n                      <ArrowUpRight size={15} className=\"rtl:-scale-x-100 transition-transform group-hover:-translate-y-0.5\" aria-hidden=\"true\" />\n                    </div>\n                  </div>\n                </Link>\n              ))}\n            </div>\n          )}\n        </section>\n      </div>\n    </main>\n  );\n}\n", "sig": "export default function TournamentsView", "drop": []}];
const SUFFIX = '.vidtourbak', NEWMARK = '.vidtournew';
const g = (s) => '\x1b[32m' + s + '\x1b[0m', r = (s) => '\x1b[31m' + s + '\x1b[0m';
if (!fs.existsSync(P('package.json'))) { console.error(r('Run this from the commander-hub folder (next to package.json).')); process.exit(1); }

if (process.argv.includes('--undo')) {
  for (const f of FILES) {
    if (fs.existsSync(P(f.path) + SUFFIX)) { fs.copyFileSync(P(f.path) + SUFFIX, P(f.path)); fs.unlinkSync(P(f.path) + SUFFIX); console.log(g('✔') + ' restored ' + f.path); }
    else if (fs.existsSync(P(f.path) + NEWMARK)) { fs.unlinkSync(P(f.path)); fs.unlinkSync(P(f.path) + NEWMARK); console.log(g('✔') + ' removed ' + f.path); }
  }
  console.log('\nClean restart to see the previous version.');
  process.exit(0);
}

// 1) check everything before writing anything
const fns = (s) => [...s.matchAll(/(?:async\s+)?function\s+([A-Za-z0-9_]+)\s*\(/g)].map((m) => m[1]);
const tables = (s) => [...s.matchAll(/\.from\(\s*["'`]([A-Za-z0-9_]+)["'`]/g)].map((m) => m[1]);
const imports = (s) => [...s.matchAll(/from\s+["']([^"']+)["']/g)].map((m) => m[1]);
const allNew = FILES.map((f) => f.src).join('\n');
const newSets = { fns: new Set(fns(allNew)), tables: new Set(tables(allNew)), imports: new Set(imports(allNew)) };
const problems = [];
for (const f of FILES) {
  if (!f.sig) continue; // brand-new file
  if (!fs.existsSync(P(f.path))) { problems.push(f.path + ' not found'); continue; }
  const cur = fs.readFileSync(P(f.path), 'utf8');
  if (cur === f.src) continue;
  if (!cur.includes(f.sig)) { problems.push(f.path + ' has unexpected contents (missing "' + f.sig + '")'); continue; }
  for (const x of fns(cur)) if (!newSets.fns.has(x)) problems.push(f.path + ': function ' + x + ' would be lost');
  for (const x of tables(cur)) if (!newSets.tables.has(x)) problems.push(f.path + ': table "' + x + '" would no longer be used');
  for (const x of imports(cur)) if (!newSets.imports.has(x) && !(f.drop || []).includes(x)) problems.push(f.path + ': import "' + x + '" would be lost');
}
if (problems.length) {
  console.error(r('Nothing was changed:'));
  problems.forEach((p) => console.error('  - ' + p));
  console.error('Send this list to Claude.');
  process.exit(1);
}

// 2) back up and write
let ok = true;
for (const f of FILES) {
  fs.mkdirSync(path.dirname(P(f.path)), { recursive: true });
  const existed = fs.existsSync(P(f.path));
  if (existed && !fs.existsSync(P(f.path) + SUFFIX) && !fs.existsSync(P(f.path) + NEWMARK) && fs.readFileSync(P(f.path), 'utf8') !== f.src) fs.copyFileSync(P(f.path), P(f.path) + SUFFIX);
  if (!existed) fs.writeFileSync(P(f.path) + NEWMARK, '');
  fs.writeFileSync(P(f.path), f.src, 'utf8');
  const good = fs.readFileSync(P(f.path), 'utf8') === f.src;
  ok = ok && good;
  console.log((good ? g('✔') : r('✘')) + ' ' + f.path + (existed ? '' : '  (new)'));
}
if (!ok) { console.error(r('\nA file did not verify. Run with --undo.')); process.exit(1); }
console.log(g('\nInstalled.') + ' Now do a clean restart:');
console.log('  Get-Process node -ErrorAction SilentlyContinue | Stop-Process -Force');
console.log('  Remove-Item -Recurse -Force .next');
console.log('  npm run dev');
console.log('Then open localhost:3000/videos and localhost:3000/tournaments (try Arabic too). Undo: node install-videos-tournaments.js --undo\n');
